import Foundation

/// ARPAbet pronunciations for the corpus words (`Corpus/lexicon.tsv`, generated by `Tools/corpus/lexicon.py`)
/// plus the phone classes the labels are built from. Keep `jawClass` in step with `JAW_HEIGHT`
/// in `Tools/corpus/coverage.py` so the app's labels match the coverage report.
struct Lexicon: Sendable {
    private let entries: [String: [String]]

    init(entries: [String: [String]]) {
        self.entries = entries
    }

    /// Lines of `word <TAB> phones`, with any further columns ignored.
    init(tsv: String) {
        var entries: [String: [String]] = [:]
        for line in tsv.split(separator: "\n") {
            let parts = line.split(separator: "\t")
            guard parts.count >= 2 else { continue }
            entries[String(parts[0])] = parts[1].split(separator: " ").map(String.init)
        }
        self.init(entries: entries)
    }

    /// The corpus words plus the decoding vocabulary.
    static let bundled = Lexicon(tsv: corpusFile("lexicon") + corpusFile("words"))

    /// The decoding vocabulary (`Corpus/words.tsv`) with each word's count in the pool books,
    /// most frequent first. The Train checklist picks its prompts from the common end.
    static let vocabulary: [(word: String, count: Int)] = corpusFile("words").split(separator: "\n").compactMap {
        let parts = $0.split(separator: "\t")
        guard parts.count >= 3, let count = Int(parts[2]) else { return nil }
        return (String(parts[0]), count)
    }

    private static func corpusFile(_ name: String) -> String {
        guard let url = Bundle.main.url(forResource: name, withExtension: "tsv", subdirectory: "Corpus") else { return "" }
        return (try? String(contentsOf: url, encoding: .utf8)) ?? ""
    }

    /// Phones with stress digits removed, or nil for an unknown word.
    func phones(_ word: String) -> [String]? {
        entries[word]?.map { $0.trimmingCharacters(in: .decimalDigits) }
    }

    /// Retain stress for IPA conversion (AH0 is schwa, not the STRUT vowel).
    func pronunciationTokens(_ word: String) -> [String]? { entries[Self.wordKey(word)] }
    var words: [String] { entries.keys.sorted() }

    static func wordKey(_ word: String) -> String { word.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() }

    /// Lower-cased words, keeping internal apostrophes ("they're"). Matches `words_of` in the tools.
    static func words(in text: String) -> [String] {
        text.lowercased().matches(of: /[a-z]+(?:'[a-z]+)?/).map { String($0.output) }
    }

    static let vowels: Set<String> = ["AA", "AE", "AH", "AO", "AW", "AY", "EH", "ER", "EY", "IH", "IY", "OW", "OY", "UH", "UW"]

    /// Jaw opening at a vowel nucleus; diphthongs are the glide between two heights.
    static func jawClass(_ phone: String) -> String? {
        switch phone {
        case "IY", "IH", "UW", "UH": "close"
        case "EY", "EH", "AH", "ER", "OW": "mid"
        case "AE", "AA", "AO": "open"
        case "AY", "AW": "open>close"
        case "OY": "mid>close"
        default: nil
        }
    }
}
